// Go source emitter for ai/image_models_generated.go. The generated file is
// package ai (same package as the ai.ImagesModel / cost types), so the
// emitter references package-ai names directly. Output is run through
// go/format.
package main

import (
	"fmt"
	"go/format"
	"math"
	"sort"
	"strconv"
	"strings"

	"github.com/ZoroSpace/pig/ai"
)

// generateImageModelsFile renders ai/image_models_generated.go from the
// sorted image model catalog.
func generateImageModelsFile(models []*ai.ImagesModel) ([]byte, error) {
	byProvider := map[ai.ImagesProviderID][]*ai.ImagesModel{}
	for _, m := range models {
		byProvider[m.Provider] = append(byProvider[m.Provider], m)
	}

	var b strings.Builder

	b.WriteString("// This file is generated by ai/scripts/generateimagemodels (pi: scripts/generate-image-models.ts).\n")
	b.WriteString("// Do not edit manually.\n\n")

	b.WriteString("package ai\n\n")

	b.WriteString("// IMAGE_MODELS is the generated image-generation catalog (pi:\n")
	b.WriteString("// image-models.generated.ts IMAGE_MODELS): provider id -> model id ->\n")
	b.WriteString("// model. pi keys the map by provider string; pig keys by the open\n")
	b.WriteString("// ImagesProviderID, mirroring MODELS.\n")
	b.WriteString("var IMAGE_MODELS = map[ImagesProviderID]map[string]ImagesModel{\n")

	providerIDs := make([]string, 0, len(byProvider))
	for providerID := range byProvider {
		providerIDs = append(providerIDs, string(providerID))
	}
	sort.Strings(providerIDs)

	for _, providerID := range providerIDs {
		models := byProvider[ai.ImagesProviderID(providerID)]
		sort.Slice(models, func(i, j int) bool { return models[i].ID < models[j].ID })

		b.WriteString("\t")
		b.WriteString(imagesProviderConstName(ai.ImagesProviderID(providerID)))
		b.WriteString(": {\n")
		for _, m := range models {
			b.WriteString("\t\t")
			b.WriteString(strconv.Quote(m.ID))
			b.WriteString(": {\n")
			writeImagesModel(&b, m, "\t\t\t")
			b.WriteString("\t\t},\n")
		}
		b.WriteString("\t},\n")
	}
	b.WriteString("}\n")

	src := b.String()
	formatted, err := format.Source([]byte(src))
	if err != nil {
		return nil, fmt.Errorf("format generated source: %w\n---\n%s", err, src)
	}
	return formatted, nil
}

func writeField(b *strings.Builder, indent, name, value string) {
	b.WriteString(indent)
	b.WriteString(name)
	b.WriteString(": ")
	b.WriteString(value)
	b.WriteString(",\n")
}

// writeImagesModel emits one ImagesModel composite literal (field order
// follows ai.ImagesModel; SamplingParams/Headers are nil for catalog data).
func writeImagesModel(b *strings.Builder, model *ai.ImagesModel, indent string) {
	writeField(b, indent, "ID", strconv.Quote(model.ID))
	writeField(b, indent, "Name", strconv.Quote(model.Name))
	writeField(b, indent, "API", imagesAPIConstName(model.API))
	writeField(b, indent, "Provider", imagesProviderConstName(model.Provider))
	writeField(b, indent, "BaseURL", strconv.Quote(model.BaseURL))
	writeImagesModalities(b, "Input", model.Input, indent)
	writeImagesModalities(b, "Output", model.Output, indent)
	writeImagesCost(b, model.Cost, indent)
}

func writeImagesModalities(b *strings.Builder, name string, modalities []ai.ModelInput, indent string) {
	b.WriteString(indent)
	b.WriteString(name)
	b.WriteString(": []ModelInput{")
	parts := make([]string, len(modalities))
	for i, m := range modalities {
		parts[i] = imagesModelInputConstName(m)
	}
	b.WriteString(strings.Join(parts, ", "))
	b.WriteString("},\n")
}

// writeImagesCost emits ModelCost; image catalog costs never carry tiers, so
// the single-line form always applies.
func writeImagesCost(b *strings.Builder, cost ai.ModelCost, indent string) {
	b.WriteString(indent)
	b.WriteString("Cost: ModelCost{ModelCostRates: ModelCostRates{")
	b.WriteString("Input: ")
	b.WriteString(floatLit(cost.Input))
	b.WriteString(", Output: ")
	b.WriteString(floatLit(cost.Output))
	b.WriteString(", CacheRead: ")
	b.WriteString(floatLit(cost.CacheRead))
	b.WriteString(", CacheWrite: ")
	b.WriteString(floatLit(cost.CacheWrite))
	b.WriteString("}},\n")
}

// floatLit renders a float64 as a compact Go literal: integers print without
// exponent, others shortest-round-trip.
func floatLit(f float64) string {
	if f == math.Trunc(f) && math.Abs(f) < 1e15 {
		return strconv.FormatFloat(f, 'f', -1, 64)
	}
	return strconv.FormatFloat(f, 'g', -1, 64)
}

func imagesAPIConstName(api ai.ImagesApi) string {
	if api == ai.ImagesApiOpenRouter {
		return "ImagesApiOpenRouter"
	}
	return "ImagesApi(" + strconv.Quote(string(api)) + ")"
}

func imagesProviderConstName(provider ai.ImagesProviderID) string {
	if provider == ai.ImagesProviderOpenRouter {
		return "ImagesProviderOpenRouter"
	}
	return "ImagesProviderID(" + strconv.Quote(string(provider)) + ")"
}

func imagesModelInputConstName(m ai.ModelInput) string {
	switch m {
	case ai.ModelInputText:
		return "ModelInputText"
	case ai.ModelInputImage:
		return "ModelInputImage"
	}
	return "ModelInput(" + strconv.Quote(string(m)) + ")"
}
